struct folio *memfd_alloc_hugetlb_folio(struct file *file, pgoff_t idx)
{
	struct inode *inode = file_inode(file);
	struct hstate *h = hstate_file(file);
	struct hugepage_subpool *spool = subpool_inode(inode);
	struct resv_map *resv = inode_resv_map(inode);
	long chg;
	struct folio *folio;
	gfp_t gfp_mask = htlb_alloc_mask(h) & ~(__GFP_HIGHMEM | __GFP_MOVABLE);
	int err;

	idx >>= huge_page_order(h);

	int nid = numa_node_id();

	if (resv)
		chg = region_chg(resv, idx, idx + 1, 1);
	else
		chg = 1;

	if (chg < 0)
		return ERR_PTR(-ENOMEM);

	if (chg) {
		if (hugepage_subpool_get_pages(spool, 1))
			return ERR_PTR(-ENOSPC);

		folio = alloc_hugetlb_folio_nodemask(h, nid, NULL, gfp_mask, true);
		if (!folio)
			folio = alloc_surplus_hugetlb_folio(h, gfp_mask, nid, NULL);

		if (!folio) {
			hugepage_subpool_put_pages(spool, 1);
			return ERR_PTR(-ENOMEM);
		}
	} else {
		folio = alloc_hugetlb_folio_reserve(h, nid, NULL, gfp_mask);
		if (!folio)
			return ERR_PTR(-ENOMEM);
	}

	if (folio_test_locked(folio))
		folio_unlock(folio);

	err = hugetlb_add_to_page_cache(folio, file->f_mapping, idx);
	if (err) {
		folio_put(folio);
		if (!chg)
			folio_set_hugetlb_restore_reserve(folio);
		return ERR_PTR(err);
	}

	folio_unlock(folio);

	return folio;
}

